using System.Reflection;
using System.Text;
using CombatV051.Domain;

internal static class CloneGenerator
{
    static string Name(Type type){if(type.IsArray)return Name(type.GetElementType())+"[]";if(type.IsGenericType)return type.GetGenericTypeDefinition().FullName.Split('`')[0]+"<"+string.Join(",",type.GetGenericArguments().Select(Name))+">";return type.FullName.Replace('+','.');}
    static FieldInfo[] Fields(Type type)=>type.GetFields(BindingFlags.Public|BindingFlags.Instance).OrderBy(f=>f.Name,StringComparer.Ordinal).ToArray();
    static bool Scalar(Type type)=>type.IsValueType||type==typeof(string);
    internal static void Generate(string destination)
    {
        var dtos=typeof(CombatState).Assembly.GetTypes().Where(t=>t.Namespace=="CombatV051.Domain"&&t.IsClass&&t.IsPublic&&t.IsDefined(typeof(SerializableAttribute),false)).OrderBy(t=>t.Name,StringComparer.Ordinal).ToArray();
        var containers=new HashSet<Type>();
        void Visit(Type t){if(Scalar(t))return;if(t.IsArray||t.IsGenericType){if(!containers.Add(t))return;if(t.IsArray)Visit(t.GetElementType());else foreach(var a in t.GetGenericArguments())Visit(a);}}
        foreach(var t in dtos)foreach(var f in Fields(t))Visit(f.FieldType);
        var all=dtos.Concat(containers.OrderBy(Name,StringComparer.Ordinal)).ToArray();
        var b=new StringBuilder("// Generated by Tools/P47StoreBench: generate. Do not hand-edit field lists.\n// Copies only data; never runs JSON deserialization or compatibility callbacks.\nusing System;\nusing System.Collections.Generic;\nnamespace CombatV051.Domain\n{\n    public static class CombatDeepClone\n    {\n");
        b.AppendLine("        public static bool TryClone(object source,out object copy)\n        {\n            if(source==null){copy=null;return true;}");
        foreach(var t in all)b.AppendLine("            if(source is "+Name(t)+" v"+Array.IndexOf(all,t)+"){copy=Copy(v"+Array.IndexOf(all,t)+");return true;}");
        b.AppendLine("            copy=null;return false;\n        }");
        b.AppendLine("        public static string FieldSignature(Type type)\n        {");
        foreach(var t in dtos)b.AppendLine("            if(type==typeof("+Name(t)+"))return \""+string.Join(";",Fields(t).Select(f=>f.Name+":"+Name(f.FieldType)))+"\";");
        b.AppendLine("            return null;\n        }");
        foreach(var t in dtos)
        {
            b.AppendLine("        public static "+Name(t)+" Copy("+Name(t)+" value)\n        {\n            if(value==null)return null;\n            return new "+Name(t)+"\n            {");
            foreach(var f in Fields(t))b.AppendLine("                "+f.Name+"="+(Scalar(f.FieldType)?"value."+f.Name:"Copy(value."+f.Name+")")+",");
            b.AppendLine("            };\n        }");
        }
        foreach(var t in containers.OrderBy(Name,StringComparer.Ordinal))
        {
            string n=Name(t);b.AppendLine("        public static "+n+" Copy("+n+" value)\n        {\n            if(value==null)return null;");
            if(t.IsArray){var item=t.GetElementType();b.AppendLine("            var result=new "+Name(item)+"[value.Length];\n            for(int i=0;i<value.Length;i++)result[i]="+(Scalar(item)?"value[i]":"Copy(value[i])")+";\n            return result;");}
            else if(t.GetGenericTypeDefinition()==typeof(List<>)){var item=t.GetGenericArguments()[0];if(Scalar(item))b.AppendLine("            return new "+n+"(value);");else b.AppendLine("            var result=new "+n+"(value.Count);\n            foreach(var item in value)result.Add(Copy(item));\n            return result;");}
            else if(t.GetGenericTypeDefinition()==typeof(Dictionary<,>)){var item=t.GetGenericArguments()[1];b.AppendLine("            var result=new "+n+"(value.Count,value.Comparer);\n            foreach(var item in value)result.Add(item.Key,"+(Scalar(item)?"item.Value":"Copy(item.Value)")+ ");\n            return result;");}
            else throw new NotSupportedException(n);
            b.AppendLine("        }");
        }
        // Same copy contract with one explicitly replaced branch; inactive modes and encounter-start snapshots stay independent.
        b.AppendLine("        public static ProfileState CopyReplacingCurrent(ProfileState value,CombatState current)\n        {\n            if(value==null)return null;\n            var result=new ProfileState\n            {");
        foreach(var f in Fields(typeof(ProfileState))){string expr;if(f.Name=="story")expr="CopyReplacingMode(value.story,value.activeMode==ProfileModeKind.Story,current)";else if(f.Name=="challenge")expr="CopyReplacingMode(value.challenge,value.activeMode==ProfileModeKind.Challenge,current)";else expr=Scalar(f.FieldType)?"value."+f.Name:"Copy(value."+f.Name+")";b.AppendLine("                "+f.Name+"="+expr+",");}
        b.AppendLine("            };\n            return result;\n        }\n        static ModeState CopyReplacingMode(ModeState value,bool active,CombatState current)\n        {\n            if(!active)return Copy(value);\n            if(value==null)return null;\n            var result=new ModeState\n            {");
        foreach(var f in Fields(typeof(ModeState))){string expr;if(f.Name=="explorationCombat")expr="string.IsNullOrEmpty(value.activeEncounterId)?Copy(current):Copy(value.explorationCombat)";else if(f.Name=="encounters")expr="CopyReplacingEncounters(value.encounters,value.activeEncounterId,current)";else expr=Scalar(f.FieldType)?"value."+f.Name:"Copy(value."+f.Name+")";b.AppendLine("                "+f.Name+"="+expr+",");}
        b.AppendLine("            };\n            return result;\n        }\n        static List<EncounterRecord> CopyReplacingEncounters(List<EncounterRecord> values,string activeId,CombatState current)\n        {\n            if(values==null)return null;\n            var result=new List<EncounterRecord>(values.Count);\n            foreach(var value in values)\n            {\n                if(value==null||value.id!=activeId){result.Add(Copy(value));continue;}\n                result.Add(new EncounterRecord\n                {");
        foreach(var f in Fields(typeof(EncounterRecord)))b.AppendLine("                    "+f.Name+"="+(f.Name=="currentCombat"?"Copy(current)":Scalar(f.FieldType)?"value."+f.Name:"Copy(value."+f.Name+")")+",");
        b.AppendLine("                });\n            }\n            return result;\n        }\n    }\n}");
        File.WriteAllText(destination,b.ToString());Console.WriteLine("Generated "+dtos.Length+" DTO types and "+containers.Count+" collection types: "+destination);
    }
}
